        let a = vec![0b0000_1111, 0b1010_1010, 0b1111_0000];
        let b = vec![0b1111_0000, 0b0101_0101, 0b1100_1100];
        // 00001111 & 11110000 = 00000000
        // 10101010 & 01010101 = 00000000
        // 11110000 & 11001100 = 11000000
